/*
 * Supplemental natural-history gallery models. All geometry and images are local.
 * The elephants were sculpted specifically for this walkthrough. Landscape
 * photographs are credited in habitatCredits. The chimpanzee, lesser kudu /
 * gerenuk, and leopard / bushpig reliefs are original interpretive artworks.
 */
const habitatTextures=new Map(),habitatMaterials=new Map(),habitatMeshData=new Map();
function habitatMaterial(key,make){
  if(!habitatMaterials.has(key))habitatMaterials.set(key,make());
  return habitatMaterials.get(key);
}
function habitatPackedMesh(key,source){
  if(!habitatMeshData.has(key))habitatMeshData.set(key,{
    points:unpackHabitatArray(source.points,Int16Array),indices:unpackHabitatArray(source.faces,Uint16Array)
  });
  return habitatMeshData.get(key);
}
function habitatTexture(key, color=true) {
  if(!habitatTextures.has(key)){
    const texture=new THREE.TextureLoader().load(habitatMedia[key]);
    if(color)texture.colorSpace=THREE.SRGBColorSpace;
    texture.anisotropy=4;
    if(key==='hide'||key==='eleBody'||key==='akeleyMarble'||key==='earth')texture.wrapS=texture.wrapT=THREE.RepeatWrapping;
    habitatTextures.set(key,texture);
  }
  return habitatTextures.get(key);
}
function unpackHabitatArray(s,Type){
  const raw=atob(s),a=new Uint8Array(raw.length);
  for(let i=0;i<raw.length;i++)a[i]=raw.charCodeAt(i);
  return new Type(a.buffer);
}
function elephantBodyGeometry(step,isCalf,poseStyle){
  const {points:packed,indices}=habitatPackedMesh('elephant',habitatElephantMesh);
  const p=new Float32Array(packed.length),colors=new Float32Array(p.length),rest=new Float32Array(p.length);
  const neck=[0,2.47,1.77];
  const gestures={
    scent:[neck,[-.015,2.21,2.10],[-.020,2.02,2.54],[.010,1.87,3.03],[.16,1.64,3.46],[.23,1.57,3.83]],
    calf:[neck,[-.04,2.06,2.04],[-.13,1.66,2.11],[-.25,1.43,2.35],[-.30,1.67,2.60],[-.30,2.03,2.72]],
    forecow:[neck,[.01,2.05,2.0],[.065,1.56,2.07],[.10,1.16,2.08],[.10,.77,1.90],[.055,.80,1.59]],
    trumpet:[neck,[.045,2.13,2.04],[.10,2.17,2.50],[.11,2.59,2.84],[.19,3.12,2.89],[.25,3.57,2.72]],
    fold:[neck,[.01,2.06,2.0],[.09,1.62,2.07],[.18,1.24,2.05],[.22,.99,1.83],[.20,1.09,1.55]],
    guard:[neck,[.035,2.09,2.04],[.16,1.70,2.13],[.39,1.41,2.17],[.64,1.21,2.03],[.86,1.13,1.82]]
  };
  const gesture=gestures[poseStyle]?new THREE.CatmullRomCurve3(gestures[poseStyle].map(p=>new THREE.Vector3(...p)),false,'centripetal'):null;
  // The underlying sculpt is shared; these small deformations pick out the
  // shoulder blades, thoracic wrinkles and the tuck behind the ribcage.
  const foldCenter=(v,r)=>Math.exp(-(v*v)/(r*r));
  const trunkCenters=[[.35,.125,2.12],[.47,.145,2.19],[.67,.120,2.20],[.94,.070,2.13],[1.25,.018,2.05],[1.62,-.035,1.99],[1.95,-.04,1.96],[2.20,-.032,1.88],[2.50,-.015,1.77]];
  for(let i=0;i<p.length;i+=3){
    let x=packed[i]/5000,y=packed[i+1]/5000,z=packed[i+2]/5000;
    // The trunk and the cuff above each foot can change pose independently.
    const t=THREE.MathUtils.clamp((2.28-y)/1.98,0,1);
    const outside=THREE.MathUtils.smoothstep(Math.abs(x),.41,.74);
    const ribs=foldCenter(y-2.0,.54)*foldCenter(z+.17,.85)*outside;
    const shoulder=foldCenter(z-.56-.14*(y-2.2),.21)*foldCenter(y-2.08,.62)*outside;
    const flank=foldCenter(z+.75,.35)*foldCenter(y-1.42,.37)*outside;
    x+=Math.sign(x)*(shoulder*.055-flank*.042+ribs*.014*Math.sin(13.7*z+1.33*y));
    y-=.025*foldCenter(x,.135)*foldCenter(z-1.59,.27)*THREE.MathUtils.smoothstep(y,2.87,3.21);
    rest.set([x,y,z],i);
    if(z>1.67&&Math.abs(x)<.44&&y<2.47){
      if(gesture){
        const u=THREE.MathUtils.clamp((2.47-y)/2.12,0,1),c=gesture.getPoint(u),tangent=gesture.getTangent(u);
        let k=1;while(k<trunkCenters.length-1&&trunkCenters[k][0]<y)k++;
        const a=trunkCenters[k-1],b=trunkCenters[k],f=THREE.MathUtils.clamp((y-a[0])/(b[0]-a[0]),0,1);
        const px=x-THREE.MathUtils.lerp(a[1],b[1],f),pz=z-THREE.MathUtils.lerp(a[2],b[2],f);
        const span=new THREE.Vector3().crossVectors(tangent,new THREE.Vector3(1,0,0)).normalize();
        const side=new THREE.Vector3().crossVectors(span,tangent).normalize();
        c.addScaledVector(side,px).addScaledVector(span,pz);
        const blend=THREE.MathUtils.smoothstep(u,0,.18);
        x=THREE.MathUtils.lerp(x,c.x,blend);y=THREE.MathUtils.lerp(y,c.y,blend);z=THREE.MathUtils.lerp(z,c.z,blend);
      }else{x+=Math.sin(step)*.41*t*t;z+=(.09+.18*Math.cos(step))*t*t;}
    }
    if(y<1.42&&Math.abs(x)>.20&&Math.abs(z)<1.50){
      z+=Math.max(0,1-y/1.42)**1.6*.22*Math.sin(step+(x<0?1:0)*Math.PI+(z<0?2.55:0));
    }
    if(isCalf&&z>1.15&&y>1.8){const k=THREE.MathUtils.smoothstep(z,1.15,1.8);y+=.085*k;x*=1+.06*k;}
    p.set([x,y,z],i);
    const side=Math.abs(x),belly=Math.exp(-((y-1.14)**2/.16+(z+.25)**2/.96))*Math.max(0,1-side/.61);
    const sideHollow=Math.exp(-((y-1.47)**2/.18+(z-.37)**2/.12))*Math.min(1,side*1.7);
    const ankle=Math.exp(-((y-.58)**2/.13))*.11;
    const value=.92-.20*belly-.07*sideHollow-ankle+.045*Math.sin(3.1*z+1.6*y)+.025*Math.cos(4.8*y-6*x);
    colors.set([value,value*.986,value*.975],i);
  }
  const geo=new THREE.BufferGeometry();
  geo.setAttribute('position',new THREE.BufferAttribute(p,3));
  geo.setAttribute('color',new THREE.BufferAttribute(colors,3));geo.setAttribute('hideRest',new THREE.BufferAttribute(rest,3));
  geo.setIndex(new THREE.BufferAttribute(indices,1));geo.computeVertexNormals();
  return geo;
}
function elephantHide(color,vertexColors){
  const material=new THREE.MeshStandardMaterial({color,roughness:.93,vertexColors,side:THREE.DoubleSide});
  material.onBeforeCompile=shader=>{
    for(const key of ['hide','eleBody','eleFace','eleBrow','eleTrunk','eleEar']){
      shader.uniforms[key+'Map']={value:habitatTexture(key,false)};
    }
    shader.vertexShader=shader.vertexShader.replace('#include <common>','#include <common>\nvarying vec3 vHideP;varying vec3 vHideN;'+(vertexColors?'attribute vec3 hideRest;':''))
      .replace('#include <begin_vertex>','#include <begin_vertex>\nvHideP='+(vertexColors?'hideRest':'position')+';vHideN=normal;');
    shader.fragmentShader=shader.fragmentShader.replace('#include <common>',`#include <common>
      varying vec3 vHideP;varying vec3 vHideN;
      uniform sampler2D hideMap,eleBodyMap,eleFaceMap,eleBrowMap,eleTrunkMap,eleEarMap;
      float hideSquare(float a){return a*a;}
      float hideHeight(vec3 p){
        vec3 n=normalize(vHideN),weight=pow(abs(n),vec3(4.0));
        weight/=max(.001,weight.x+weight.y+weight.z);
        float h=dot(weight,vec3(texture2D(hideMap,p.zy*vec2(1.3,1.5)).r,
          texture2D(hideMap,p.xz*vec2(1.5,1.3)).r,texture2D(hideMap,p.xy*1.5).r));
        float shoulder=dot(weight,vec3(texture2D(eleBodyMap,p.zy*vec2(2.25,2.7)).r,
          texture2D(eleBodyMap,p.xz*vec2(2.55,2.35)).r,texture2D(eleBodyMap,p.xy*2.53).r));
        float grain=mix(h,shoulder,.67);
        ${vertexColors?`
        float cheek=texture2D(eleFaceMap,clamp((p.zy-vec2(1.02,1.99))/vec2(1.09,1.25),.005,.995)).r;
        float face=smoothstep(.98,1.19,p.z)*smoothstep(1.90,2.22,p.y);
        grain=mix(grain,cheek,face*(.57+.31*abs(n.x)));
        float brow=texture2D(eleBrowMap,clamp(vec2(.5+p.x/.84,(p.y-2.38)/.89),.005,.995)).r;
        float forehead=smoothstep(1.56,1.86,p.z)*smoothstep(2.36,2.62,p.y)*(1.-smoothstep(.22,.47,abs(p.x)));
        grain=mix(grain,brow,forehead*.82);
        float trunk=smoothstep(1.62,1.87,p.z)*(1.-smoothstep(2.40,2.68,p.y));
        float axis=.12*(1.-smoothstep(.63,1.45,p.y))-.035*smoothstep(.70,1.53,p.y);
        float radius=mix(.084,.24,smoothstep(.34,2.45,p.y));
        float u=.5+.48*clamp((p.x-axis)/radius,-1.,1.);
        float creases=texture2D(eleTrunkMap,vec2(u,clamp((p.y-.35)/2.22,.009,.991))).r;
        grain=mix(grain,creases,trunk*.90);
        float leg=smoothstep(.18,.34,abs(p.x))*(1.-smoothstep(1.28,1.55,p.y))*(1.-smoothstep(1.4,1.64,abs(p.z)));
        float cuff=exp(-hideSquare((p.y-.29)/.17))+.55*exp(-hideSquare((p.y-.92)/.18));
        float line=(.5+.5*cos(p.y*89.+4.*sin(6.*p.x+1.6*p.z)+.9*sin(11.*p.z)));
        float bodyfold=exp(-hideSquare((p.z-.48)/.38))*smoothstep(.42,.76,abs(p.x));
        grain-=cuff*leg*.15*pow(line,3.)+bodyfold*.065*pow(.5+.5*cos(p.z*40.+5.*p.y),3.);`:`
        vec2 earCoord=clamp((vec2(abs(p.x),p.y)-vec2(.33,1.82))/vec2(1.03,1.44),.004,.996);
        float pinna=texture2D(eleEarMap,earCoord).r;
        grain=mix(grain,pinna,.94);
        grain-=.12*exp(-hideSquare((abs(p.x)-.52)/.165))*exp(-hideSquare((p.y-2.68)/.41));`}
        return grain;
      }`)
      .replace('#include <color_fragment>',`#include <color_fragment>
        float elephantSurface=hideHeight(vHideP);
        diffuseColor.rgb*=clamp(.14+1.66*elephantSurface,.33,1.55);`)
      .replace('#include <normal_fragment_maps>',`#include <normal_fragment_maps>
        vec3 eleQ0=dFdx(-vViewPosition),eleQ1=dFdy(-vViewPosition);
        vec3 eleRx=cross(eleQ1,normal),eleRy=cross(normal,eleQ0);
        float eleDet=dot(eleQ0,eleRx);
        normal=normalize(max(abs(eleDet),1e-8)*normal-sign(eleDet)*.012*(dFdx(elephantSurface)*eleRx+dFdy(elephantSurface)*eleRy));`);
  };
  material.customProgramCacheKey=()=>vertexColors?'elephant-body-skin-v3':'elephant-ear-skin-v3';
  return material;
}
function sculptEar(side,pose,calf){
  // A fan-shaped pinna has a raised dorsum, deeply folded root and scalloped rim.
  const controls=[[.33,2.98,1.52],[.56,3.15,1.46],[.81,3.20,1.34],[1.01,3.04,1.14],
    [1.10,2.91,1.08],[1.20,2.71,1.04],[1.12,2.55,1.07],[1.02,2.35,1.12],
    [.92,2.30,1.09],[.83,2.14,1.14],[.71,1.97,1.22],[.65,1.88,1.31],
    [.57,2.08,1.43],[.45,2.24,1.52],[.34,2.57,1.58]];
  const curve=new THREE.CatmullRomCurve3(controls.map(p=>new THREE.Vector3(...p)),true,'centripetal');
  const n=64,m=14,points=[],indices=[],root=new THREE.Vector3(.40,2.71,1.61);
  for(let j=0;j<=m;j++)for(let i=0;i<n;i++){
    const u=i/n,r=Math.max(.002,j/m),e=curve.getPointAt(u),v=root.clone().lerp(e,r);
    const channel=.006*Math.sin(37*u-1.4*r+.77*Math.sin(u*13))+.0018*Math.sin(u*101+2*r);
    v.z+=.065*Math.sin(Math.PI*r)+channel*Math.sin(Math.PI*r)**.7;
    const reach=THREE.MathUtils.clamp((v.x-.34)/.86,0,1);
    v.z-=(.34+.15*Math.sin(pose+side*1.23))*reach**1.45+.055*Math.sin(6.2*u)*r*r;
    v.z+=.067*Math.sin(2.9*Math.PI*u+.24)*Math.sin(Math.PI*r);
    v.y+=r**6*(.014*Math.sin(81*u+pose)+.008*Math.sin(133*u));
    v.z+=.077*Math.exp(-((v.y-3.06)**2)/.012)*r;
    v.z+=(.18*Math.sin(pose+side*1.5)+.12)*r*r+.009*Math.cos(u*92+pose)*r**6;
    v.x=.34+(v.x-.34)*1.17;v.y=2.69+(v.y-2.69)*1.10;
    if(calf){v.x=.34+(v.x-.34)*1.05;v.y+=.07;}
    points.push(side*v.x,v.y,v.z);
    if(j<m){const a=j*n+i,b=j*n+(i+1)%n,c=a+n,d=b+n;indices.push(a,b,c,c,b,d);}
  }
  // The folded pinna has a thin rim that remains visible in a side view.
  const count=points.length/3,face=indices.length;
  for(let i=0;i<count;i++){
    const radius=Math.floor(i/n)/m;
    points.push(points[i*3],points[i*3+1],points[i*3+2]-.018-.020*(1-radius));
  }
  for(let i=0;i<face;i+=3)indices.push(indices[i]+count,indices[i+2]+count,indices[i+1]+count);
  for(let i=0;i<n;i++){
    const a=m*n+i,b=m*n+(i+1)%n;indices.push(a,b,b+count,a,b+count,a+count);
  }
  const geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.Float32BufferAttribute(points,3));geo.setIndex(indices);geo.computeVertexNormals();return geo;
}
function curvedTube(path,radius,color,radial=12,rings=24){
  const curve=new THREE.CatmullRomCurve3(path.map(p=>new THREE.Vector3(...p))),frames=curve.computeFrenetFrames(rings,false);
  const pos=[],indices=[],colors=[];
  for(let j=0;j<=rings;j++){
    const t=j/rings,c=curve.getPointAt(t),r=radius(t),tint=new THREE.Color(color(t));
    for(let i=0;i<radial;i++){
      const a=i*Math.PI*2/radial;
      const p=c.clone().addScaledVector(frames.normals[j],r*Math.cos(a)).addScaledVector(frames.binormals[j],r*Math.sin(a));
      pos.push(p.x,p.y,p.z);colors.push(tint.r,tint.g,tint.b);
      if(j<rings){const b=j*radial+i,k=j*radial+(i+1)%radial;indices.push(b,k,b+radial,b+radial,k,k+radial);}
    }
  }
  const geo=new THREE.BufferGeometry();geo.setIndex(indices);geo.setAttribute('position',new THREE.Float32BufferAttribute(pos,3));geo.setAttribute('color',new THREE.Float32BufferAttribute(colors,3));geo.computeVertexNormals();return geo;
}
function addElephantHerd(parent){
  // Longitudinal formation reconstructed from museum views. The middle bull
  // extends his trunk to scent the air and the rear-guard bull faces back.
  const herd=[[.60,3.66,.85,-.13,'forecow'],[-.69,2.50,.56,.13,'calf'],[-.47,.61,1.04,.065,'scent'],
    [1.16,.40,.78,.17,'fold'],[-1.16,-1.66,.81,-.12,''],[.88,-2.13,.82,.36,'trumpet'],
    [-.90,-3.54,.66,-.71,''],[.29,-4.15,.89,Math.PI-.32,'guard']];
  const ivory=new THREE.MeshStandardMaterial({vertexColors:true,side:THREE.DoubleSide,roughness:.48});
  herd.forEach(([x,z,size,yaw,gesture],j)=>{
    const pose=j*1.47,calf=size<.7;
    const frame=new THREE.Group(),group=new THREE.Group();
    frame.position.set(x,.709,z);frame.scale.z=1.25/(44/26);
    group.rotation.y=yaw;group.scale.setScalar(size);frame.add(group);
    const skin=['#68635f','#72675e','#68625f','#756f6b','#706963','#67615e','#716b64','#696663'][j];
    group.add(new THREE.Mesh(elephantBodyGeometry(pose,calf,gesture),elephantHide(skin,true)));
    const parts=new GalleryMesh();
    const ears=elephantHide(skin,false);
    for(const side of [-1,1]){
      group.add(new THREE.Mesh(sculptEar(side,pose,calf),ears));
      // Lids, sclera and pupil are distinct on either side of the bridge of the nose.
      const xx=side*.505;
      parts.ell([xx,2.683,1.660],[.044,.052,.067],'#51473a');
      parts.ell([xx+side*.031,2.681,1.665],[.024,.034,.046],'#241e16');
      parts.ell([xx+side*.052,2.687,1.675],[.008,.010,.010],'#d7cdb5');
      const brow=[[xx,2.665,1.595],[xx+side*.024,2.725,1.635],[xx+side*.024,2.731,1.684],[xx,2.689,1.730]];
      for(let k=1;k<brow.length;k++)parts.rod(brow[k-1],brow[k],.017,.014,'#817461');
      const lengths=[[.62,.77],[.27,.34],[.91,1],[.57,.65],[.75,.70],[.66,.75],[.39,.44],[.93,.85]];
      const tuskLength=lengths[j][side<0?0:1],bull=j===2||j===7;
      const base=[side*.30,2.23,1.69],tuskPath=[base,[side*.335,2.09,1.79],[side*.37,1.95,1.98],
        [side*.43,1.84,2.22],[side*.50,1.81,2.46],[side*.55,bull?1.94:1.84,2.67],[side*.56,bull?2.08:1.88,2.79]];
      const path=tuskPath.map(p=>p.map((v,k)=>base[k]+(v-base[k])*tuskLength));
      const tusk=curvedTube(path,t=>(calf?.053:bull?.120:.085)*(1-t)**.67+.001,
       t=>new THREE.Color('#886d47').lerp(new THREE.Color('#e1cba3'),Math.min(1,t*3)).getStyle(),16,28);
      group.add(new THREE.Mesh(tusk,ivory));
      for(const fore of [-1,1]){
        const px=side*(fore<0?.46:.50),pz=fore*(fore<0?.92:.84)+.055*side*fore+(fore<0?-.12:.06)+.22*Math.sin(pose+(side<0?Math.PI:0)+(fore<0?2.55:0));
        const count=fore<0?3:4;
        for(let k=0;k<count;k++){const a=(k/(count-1)-.5)*1.6;parts.ell([px+.208*Math.sin(a),.072,pz+.236*Math.cos(a)],[.048,.052,.029],'#8d806d');}
      }
    }
    const tail=[[.08,2.17,-1.59],[.10,1.84,-1.70],[.13,1.17,-1.73],[.16+.13*Math.cos(pose),.68,-1.75],[.22+.16*Math.cos(pose),.56,-1.72]];
    group.add(new THREE.Mesh(curvedTube(tail,t=>.067*(1-t)+.016,()=>skin,10,16),ivory));
    for(let k=0;k<10;k++){
      const p=tail[4],a=k*Math.PI/5;
      parts.rod([p[0]+.015*Math.cos(a),p[1]+.07,p[2]+.015*Math.sin(a)],
        [p[0]+.035*Math.cos(a)+.025,p[1]-.14+(k%3)*.012,p[2]+.035*Math.sin(a)],.010,.003,'#493f32');
    }
    group.add(parts.finish(true));group.traverse(m=>{if(m.isMesh){m.castShadow=true;m.receiveShadow=true;}});
    parent.add(frame);
  });
}

// Hydrofoil sections interpolate the flukes and pectorals continuously.
// Modelling both faces is important at the balcony where visitors see above
// the flippers and back underneath them while walking around the gallery.
function addWhaleFins(parent){
  const profiles=[
    {root:[24,6.74,2.85],colors:['#718b99','#b8c4c4'],sections:[
      [1.05,-.16,.08,.71,.20],[1.47,-.29,-.04,.74,.20],[1.92,-.53,-.30,.64,.145],
      [2.38,-.77,-.62,.48,.112],[2.82,-.96,-1.01,.31,.085],[3.16,-1.115,-1.38,.145,.044],[3.35,-1.16,-1.58,.008,.007]]},
    {root:[24,7.95,-9.22],colors:['#607f90','#9bb1b9'],sections:[
      [0,0,.105,.245,.11],[.24,.005,-.13,.55,.15],[.51,.024,-.31,.72,.17],[.96,.075,-.43,.88,.16],
      [1.48,.13,-.61,.78,.13],[1.98,.19,-.86,.56,.094],[2.40,.23,-1.10,.35,.068],[2.70,.25,-1.37,.16,.039],[2.86,.26,-1.52,.006,.009]]}
  ];
  const material=habitatMaterial('whale-hydrofoil',()=>new THREE.MeshStandardMaterial({vertexColors:true,side:THREE.DoubleSide,roughness:.69,emissive:'#667c8e',emissiveIntensity:.068}));
  for(const {root,colors,sections} of profiles){
    const hi=new THREE.Color(colors[0]),lo=new THREE.Color(colors[1]);
    const curve=new THREE.CatmullRomCurve3(sections.map(a=>new THREE.Vector3(...a.slice(0,3))),false,'catmullrom',.34);
    const sizes=new THREE.CatmullRomCurve3(sections.map((a,i)=>new THREE.Vector3(a[3],a[4],i)),false,'catmullrom',.30);
    for(const side of [-1,1]){
      const rings=44,cuts=40,p=[],col=[],indices=[];
      for(let j=0;j<=rings;j++){
        const u=j/rings,c=curve.getPoint(u),s=sizes.getPoint(u);
        for(let i=0;i<cuts;i++){
          const t=i/cuts*Math.PI*2,st=Math.sin(t),ct=Math.cos(t);
          const sweep=.028*Math.sin(Math.PI*u)*ct;
          p.push(root[0]+side*c.x,root[1]+c.y+st*Math.max(.004,s.y)+sweep,root[2]+c.z+ct*Math.max(.005,s.x));
          const tint=lo.clone().lerp(hi,THREE.MathUtils.smoothstep(st,-.20,.30));
          const shade=.96+.019*Math.sin(17*u+3.3*ct)+.014*Math.sin(27*u-12*ct);
          col.push(tint.r*shade,tint.g*shade,tint.b*shade);
          if(j<rings){
            const a=j*cuts+i,b=j*cuts+(i+1)%cuts,c=a+cuts,d=b+cuts;
            if(side>0)indices.push(a,c,b,c,d,b);else indices.push(a,b,c,c,b,d);
          }
        }
      }
      const geo=new THREE.BufferGeometry();
      geo.setAttribute('position',new THREE.Float32BufferAttribute(p,3));
      geo.setAttribute('color',new THREE.Float32BufferAttribute(col,3));
      geo.setIndex(indices);geo.computeVertexNormals();
      const fin=new THREE.Mesh(geo,material);fin.castShadow=true;fin.receiveShadow=true;parent.add(fin);
    }
  }
}

// In the museum the nose dives toward the entrance stairs, slightly to one
// side. The tail reaches back over the opposite side of the Andros display.
// Photographs also show the peduncle bending back down from the vaulted back.
function poseOceanWhale(mesh){
  const geometry=mesh.geometry;
  const stations=[[-11,-1.32],[-9.55,-1.24],[-8.8,-.71],[-7.8,.95],[-6.3,2.68],[-4.5,3.04],[-2.25,2.84],
    [0,2.15],[2.2,1.51],[3.8,.90],[5.25,.35],[6.7,-.33],[8,-.91],[8.9,-1.25],[9.4,-1.45],[9.64,-1.59]];
  const pitchAt=z=>{
    let i=1;while(i<stations.length-1&&z>stations[i][0])i++;
    const [x0,y0]=stations[i-1],[x1,y1]=stations[i],h=x1-x0,t=THREE.MathUtils.clamp((z-x0)/h,0,1);
    const secant=k=>(stations[k+1][1]-stations[k][1])/(stations[k+1][0]-stations[k][0]);
    const slope=k=>{
      if(k===0)return secant(0);
      if(k===stations.length-1)return secant(k-1);
      const a=secant(k-1),b=secant(k);return a*b>0?2*a*b/(a+b):0;
    };
    const ka=slope(i-1),kb=slope(i);
    const c=3*t*t-2*t*t*t;
    return [y0*(1-c)+y1*c+h*(ka*t*(1-t)*(1-t)-kb*t*t*(1-t)),
      6*t*(1-t)*(y1-y0)/h+ka*(1-4*t+3*t*t)+kb*(-2*t+3*t*t)];
  };
  const angle=Math.PI-.315,co=Math.cos(angle),si=Math.sin(angle);
  if(mesh.isInstancedMesh){
    // The small glass eyes use the shared gallery sphere. Move each instance;
    // the unit geometry is also used by mounts throughout the museum.
    const model=new THREE.Matrix4(),basis=new THREE.Matrix4();
    for(let i=0;i<mesh.count;i++){
      mesh.getMatrixAt(i,model);
      const e=model.elements,x=e[12]-24,y=e[13],z=e[14],[rise,slope]=pitchAt(z);
      model.setPosition(0,0,0);
      basis.set(co,0,si,0,0,1,slope,0,-si,0,co,0,0,0,0,1);
      model.premultiply(basis).setPosition(23.13+co*x+si*z,y+rise,-si*x+co*z);
      mesh.setMatrixAt(i,model);
    }
    mesh.instanceMatrix.needsUpdate=true;mesh.computeBoundingBox();mesh.computeBoundingSphere();return;
  }
  const p=geometry.getAttribute('position'),n=geometry.getAttribute('normal');
  for(let i=0;i<p.count;i++){
    const x=p.getX(i)-24,y=p.getY(i),z=p.getZ(i),[rise,slope]=pitchAt(z);
    p.setXYZ(i,23.13+co*x+si*z,y+rise,-si*x+co*z);
    if(n){
      const nx=n.getX(i),ny=n.getY(i),nz=n.getZ(i)-slope*ny,inv=1/Math.hypot(nx,ny,nz);
      n.setXYZ(i,(co*nx+si*nz)*inv,ny*inv,(-si*nx+co*nz)*inv);
    }
  }
  p.needsUpdate=true;if(n)n.needsUpdate=true;
  geometry.computeBoundingBox();geometry.computeBoundingSphere();
}

function addBlueWhaleSkin(parent){
  const slices=128,rings=134,positions=[],normals=[],uv=[],indices=[],tau=Math.PI*2;
  for(let j=0;j<=rings;j++){
    const v=j/rings,z=-9.55+19.17*v;
    for(let i=0;i<=slices;i++){
      const u=i/slices,t=tau*u;
      const pos=blueWhaleSurface(z,t);
      const across=new THREE.Vector3().fromArray(blueWhaleSurface(z,t+.001)).sub(new THREE.Vector3().fromArray(blueWhaleSurface(z,t-.001)));
      const along=new THREE.Vector3().fromArray(blueWhaleSurface(Math.min(9.62,z+.003),t)).sub(new THREE.Vector3().fromArray(blueWhaleSurface(Math.max(-9.55,z-.003),t)));
      const n=across.cross(along).normalize();
      positions.push(...pos);normals.push(n.x,n.y,n.z);uv.push(u,v);
      if(i<slices&&j<rings){
        const a=j*(slices+1)+i,b=a+1,c=a+slices+1,d=c+1;
        indices.push(a,b,c,c,b,d);
      }
    }
  }
  const geo=new THREE.BufferGeometry();
  geo.setAttribute('position',new THREE.Float32BufferAttribute(positions,3));
  geo.setAttribute('normal',new THREE.Float32BufferAttribute(normals,3));
  geo.setAttribute('uv',new THREE.Float32BufferAttribute(uv,2));geo.setIndex(indices);
  const skin=habitatTexture('whaleSkin'),bump=habitatTexture('whaleBump',false);
  skin.wrapS=bump.wrapS=THREE.RepeatWrapping;
  const skinMaterial=habitatMaterial('blue-whale',()=>new THREE.MeshStandardMaterial({map:skin,bumpMap:bump,bumpScale:.018,emissiveMap:skin,emissive:'#93abc5',emissiveIntensity:.20,roughness:.67}));
  const whale=new THREE.Mesh(geo,skinMaterial);whale.castShadow=true;whale.receiveShadow=true;parent.add(whale);
  addWhaleFins(parent);
  parent.traverse(piece=>{if(piece.geometry)poseOceanWhale(piece);});
}

// A relief sheet projects the diorama photograph into the case. The depth
// displacement is along the ray to its original viewpoint: the image stays
// registered there, and exhibits parallax as a visitor moves across the window.
function addHabitatCase(parent,options){
  const {key,x,z,direction,sideY=0,width,lo,hi,back,relief,front,alongX=true}=options;
  const rightX=alongX?direction:0,rightZ=alongX?0:-direction,normalX=alongX?0:direction,normalZ=alongX?direction:0;
  const dimensions=(w,h,d)=>alongX?[w,h,d]:[d,h,w];
  const place=(u,y,d)=>[x+rightX*u+normalX*d,y+sideY,z+rightZ*u+normalZ*d];
  const array=habitatDepth[key]?unpackHabitatArray(habitatDepth[key],Uint8Array):null;
  const nx=array?85:37,ny=array?43:6,pos=[],uv=[],indices=[],facingDistance=4.75;
  const rimBlend=q=>THREE.MathUtils.smoothstep(q,0,.085);
  for(let row=0;row<ny;row++)for(let col=0;col<nx;col++){
    const u=col/(nx-1),v=row/(ny-1),c=2*u-1;
    const border=rimBlend(Math.min(u,1-u,v,1-v));
    const depth=array?array[Math.round(v*63)*128+Math.round(u*127)]/255:0;
    const paintedCurve=.045*c**4;
    const projection=depth*relief*border;
    const scale=1-projection/(facingDistance-back);
    const fullY=hi+(lo-hi)*v;
    const focusHeight=2.15;
    pos.push(...place(c*width*.5*scale,focusHeight+(fullY-focusHeight)*scale,back+paintedCurve+projection));
    uv.push(u,1-v);
    if(row<ny-1&&col<nx-1){const a=row*nx+col,b=a+1,c=a+nx,d=c+1;indices.push(a,c,b,b,c,d);}
  }
  const geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.Float32BufferAttribute(pos,3));
  geo.setAttribute('uv',new THREE.Float32BufferAttribute(uv,2));geo.setIndex(indices);
  const sceneMaterial=habitatMaterial('photo-'+key,()=>new THREE.MeshBasicMaterial({map:habitatTexture(key),side:THREE.DoubleSide,toneMapped:false}));
  const scene=new THREE.Mesh(geo,sceneMaterial);scene.name='Habitat relief · '+key;parent.add(scene);

  if(options.name)addHabitatTrim(parent,options,place,dimensions,front,lo,hi);
  const frame=new GalleryMesh();
  const box=(u,y,d,w,h,t,c)=>frame.box(place(u,y,d),dimensions(w,h,t),c);
  const black=key==='squid'?'#101922':'#292923';
  const frameTone=key==='squid'?'#27313a':key==='reef'||key==='kelp'?'#4b5d58':'#524839';
  const lip=key==='squid'?'#414b54':key==='reef'||key==='kelp'?'#869a88':'#9a8b70';
  const caseWidth=options.caseWidth||width,inner=options.name?width:caseWidth-.24,height=hi-lo;
  const bottom=lo-.014,top=hi+.008;
  for(const sign of [-1,1]){
    box(sign*(caseWidth/2-.075),(lo+hi)/2,front,.15,height+.20,.14,frameTone);
    box(sign*(inner/2+.007),(lo+hi)/2,front+.073,.021,height,.014,lip);
    // Set-back side returns prevent the wall behind a case appearing at oblique angles.
    const edge=sign*(width/2),near=sign*(inner/2+.014),d=back+.012;
    const a=place(edge,lo,d),b=place(edge,hi,d),c=place(near,hi,front-.05),e=place(near,lo,front-.05);
    frame.tri(a,b,c,black);frame.tri(a,c,e,black);
  }
  box(0,bottom,front,caseWidth+.035,.11,.16,frameTone);
  box(0,bottom+.052,front+.071,inner,.016,.026,lip);
  box(0,top,front,caseWidth+.035,.12,.16,frameTone);
  box(0,top-.056,front+.071,inner,.016,.026,lip);
  {
    const dark=key==='squid'?'#0b1119':key==='reef'||key==='kelp'?'#253c3e':'#342f24';
    const far=place(-width/2,lo,back+.012),farR=place(width/2,lo,back+.012);
    const near=place(-inner/2,lo,front+.01),nearR=place(inner/2,lo,front+.01);
    frame.tri(far,farR,nearR,dark);frame.tri(far,nearR,near,dark);
  }
  parent.add(frame.finish());
}

// The restored Andros artwork continues above the visitor mezzanine. The
// independently painted cay and flying flamingos sit in an arched cyclorama.
function addAndrosSky(parent){
  const cx=31.7,cz=12.18,half=3.41,low=4.14,spring=5.54,rise=2.90;
  const xs=100,ys=26,pos=[],uv=[],index=[];
  const shape=(t,h)=>[cx-(t*half),h,cz-.24*t*t];
  for(let i=0;i<=xs;i++){
    const u=i/xs,t=2*u-1,upper=spring+rise*Math.sqrt(Math.max(0,1-t*t));
    for(let j=0;j<=ys;j++){
      const q=j/ys,y=low+(upper-low)*q;
      pos.push(...shape(t,y));uv.push(u,(y-low)/(spring+rise-low));
      if(i<xs&&j<ys){const a=i*(ys+1)+j,b=a+ys+1,c=a+1,d=b+1;index.push(a,b,c,c,b,d);}
    }
  }
  const geo=new THREE.BufferGeometry();
  geo.setAttribute('position',new THREE.Float32BufferAttribute(pos,3));
  geo.setAttribute('uv',new THREE.Float32BufferAttribute(uv,2));geo.setIndex(index);
  const mat=habitatMaterial('androsSky',()=>new THREE.MeshBasicMaterial({map:habitatTexture('androsSky'),side:THREE.DoubleSide,toneMapped:false}));
  parent.add(new THREE.Mesh(geo,mat));
  const frame=new GalleryMesh(),edge='#647475',trim='#91978c',dark='#3f4c4c';
  const lip=(t,extra,yOffset)=>[cx-(half+extra)*Math.cos(t),spring+(rise+extra)*Math.sin(t)+yOffset,cz-.24*Math.cos(t)**2-.07];
  for(let i=0;i<84;i++){
    const a=i*Math.PI/84,b=(i+1)*Math.PI/84;
    for(const [start,stop,color] of [[0,.047,trim],[.047,.108,dark],[.108,.141,edge]]){
      const q=[lip(a,start,0),lip(b,start,0),lip(b,stop,0),lip(a,stop,0)];
      frame.tri(q[0],q[1],q[2],color);frame.tri(q[0],q[2],q[3],color);
    }
  }
  for(const side of [-1,1]){
    frame.box([cx+side*(half+.077),(spring+low)/2,cz-.27],[.14,spring-low,.10],edge);
    frame.box([cx+side*(half+.018),(spring+low)/2,cz-.30],[.032,spring-low,.10],trim);
  }
  frame.box([cx,low-.035,cz-.17],[2*half+.29,.080,.27],edge);
  parent.add(frame.finish());
}

function addHabitatArt(parent,id){
  if(id==='akeley'||id==='mezzanine'){
    akeleyFurnishings(parent);addElephantHerd(parent);
    for(const c of akeleyCases){
      if(!habitatMedia[c.key])continue;
      const cap={rhino:1.66,white:1.74,ostrich:1.94,gorilla:1.96,water:2.155,klipspringer:2.17};
      const aperture=Math.min(c.width-(c.alongX?.54:.20),c.alongX&&cap[c.key]?cap[c.key]*3.33:Infinity);
      const sideRelief=c.alongX?.56:.38;
      addHabitatCase(parent,{...c,width:aperture,caseWidth:c.width,lo:.67,hi:c.alongX?4.00:3.65,
        back:.16,front:c.alongX?.79:.54,relief:sideRelief});
    }
  } else if(id==='ocean'){
    for(const window of oceanHabitatWindows)addHabitatCase(parent,window);
    addAndrosSky(parent);
  }
}

// The shallow decorative friezes, bronze panels, oak benches and earth bed
// follow the proportions and finishes visible in views of Akeley Hall.
function akeleyFurnishings(parent){
  const scenery=new GalleryMesh();
  const put=(x,y,z,w,h,d,color)=>scenery.box([x,y,z],[w,h,d],color);
  const bronze='#475246',oxide='#364034',line='#9d9576',floor='#c4bdab',edge='#a49a82';
  const border=.052;
  for(const sign of [-1,1]){
    for(const cross of [false,true]){
      const extent=cross?7.20:7.93,axis=cross?7.89:7.21,spans=cross?6:7,full=2*extent;
      function fascia(at,y,inset,width,height,depth,color){
        const normal=sign*(axis-inset);
        if(cross)put(at,y,normal,width,height,depth,color);
        else put(normal,y,at,depth,height,width,color);
      }
      fascia(0,5.80,.07,full,1.26,.23,bronze);
      fascia(0,5.22,.22,full,.10,.08,oxide);
      fascia(0,5.31,.20,full,.045,.055,line);
      fascia(0,6.43,.02,full+.16,.095,.38,edge);
      for(let i=0;i<spans;i++){
        const w=full/spans,c=-extent+(i+.5)*w;
        for(const s of [-1,1]){
          fascia(c+s*(w*.42),5.85,.193,border,.755,.024,line);
          fascia(c,5.85+s*.381,.193,w*.84+border,.039,.024,line);
          fascia(c+s*(w*.485),5.85,.193,.027,.78,.023,line);
        }
      }
    }
  }
  // The lower gallery has a continuous pale, patterned ceiling over the atrium.
  const ceiling=new THREE.Mesh(new THREE.BoxGeometry(23.86,.20,25.84),habitatMaterial('akeleyCeiling',()=>new THREE.MeshStandardMaterial({color:floor,emissive:'#d8ccaf',emissiveIntensity:.22,roughness:.98})));
  ceiling.position.y=10.77;parent.add(ceiling);
  for(const x of [-9,-5.35,-1.76,1.76,5.35,9])put(x,10.645,0,.075,.10,25.80,edge);
  for(let z=-12;z<12.3;z+=3.05)put(0,10.65,z,23.80,.095,.075,edge);
  for(let x=-8;x<9;x+=4)for(let z=-9.15;z<=9.16;z+=6.1){
    put(x,10.625,z,.35,.135,.28,'#8e8979');put(x,10.55,z,.22,.036,.15,'#ede4ca');
  }
  parent.add(scenery.finish());
  akeleyElephantPlinth(parent);elephantBronzePlaque(parent);
}

function akeleyElephantPlinth(parent){
  const batch=new GalleryMesh(),trim='#95724d',dark='#584638';
  const outline=[[-1.66,-6.10],[1.66,-6.10],[2.30,-5.39],[2.30,5.39],[1.66,6.10],[-1.66,6.10],[-2.30,5.39],[-2.30,-5.39]];
  const woodMap=habitatTexture('plinthWood');woodMap.wrapS=woodMap.wrapT=THREE.RepeatWrapping;
  const wood=habitatMaterial('plinthWood',()=>new THREE.MeshStandardMaterial({color:'#d9c2a5',map:woodMap,roughness:.70,side:THREE.DoubleSide}));
  const soilTex=habitatTexture('earth');soilTex.wrapS=soilTex.wrapT=THREE.RepeatWrapping;
  const earth=habitatMaterial('earth',()=>new THREE.MeshStandardMaterial({map:soilTex,roughness:.98,side:THREE.DoubleSide}));
  function strip(scale,y0,y1,material){
    const pos=[],uv=[],ind=[];
    for(let i=0;i<outline.length;i++){
      const a=outline[i],b=outline[(i+1)%outline.length],len=Math.hypot(b[0]-a[0],b[1]-a[1]);
      const n=pos.length/3;
      pos.push(a[0]*scale,y0,a[1]*scale,b[0]*scale,y0,b[1]*scale,b[0]*scale,y1,b[1]*scale,a[0]*scale,y1,a[1]*scale);
      uv.push(0,0,len/2.2,0,len/2.2,(y1-y0)*1.4,0,(y1-y0)*1.4);ind.push(n,n+1,n+2,n,n+2,n+3);
    }
    const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(pos,3));
    g.setAttribute('uv',new THREE.Float32BufferAttribute(uv,2));g.setIndex(ind);g.computeVertexNormals();
    const m=new THREE.Mesh(g,material);m.receiveShadow=true;m.castShadow=true;parent.add(m);
  }
  strip(1.024,0,.095,new THREE.MeshStandardMaterial({color:dark,roughness:.73,side:THREE.DoubleSide}));
  strip(1.01,.081,.17,wood);strip(.976,.16,.65,wood);strip(1.003,.637,.722,wood);
  // Vertical oak joints and inset field panels are visible on the actual
  // chamfered case. Fine bevel lines keep them discernible at floor level.
  for(let k=0;k<outline.length;k++){
    const a=outline[k],b=outline[(k+1)%outline.length],dx=b[0]-a[0],dz=b[1]-a[1],len=Math.hypot(dx,dz);
    const pieces=Math.max(3,Math.round(len/.165)),sx=dx/len,sz=dz/len,ox=sz*.010,oz=-sx*.010;
    for(let j=1;j<pieces;j++){
      const u=j/pieces,x=(a[0]+dx*u)*.977,z=(a[1]+dz*u)*.977;
      batch.rod([x+ox,.178,z+oz],[x+ox,.634,z+oz],.0055,.0055,'#60492e');
    }
  }
  const vertices=[],tex=[],indices=[];
  const rows=42,columns=18;
  for(let j=0;j<=rows;j++)for(let i=0;i<=columns;i++){
    const z=-6.07+j/rows*12.14,half=2.28-Math.max(0,Math.abs(z)-5.39)*.89,x=(2*i/columns-1)*half;
    const ripple=.014*Math.sin(4.1*x+z)*Math.cos(2.5*z-x)+.007*Math.sin(9*z+3.5*x);
    vertices.push(x,.707+ripple,z);tex.push(x*.47,z*.47);
    if(j<rows&&i<columns){const a=j*(columns+1)+i,b=a+1,c=a+columns+1,d=c+1;indices.push(a,c,b,b,c,d);}
  }
  const geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.Float32BufferAttribute(vertices,3));
  geo.setAttribute('uv',new THREE.Float32BufferAttribute(tex,2));geo.setIndex(indices);geo.computeVertexNormals();
  const bed=new THREE.Mesh(geo,earth);bed.receiveShadow=true;parent.add(bed);
  for(const side of [-1,1]){
    batch.box([side*2.43,.355,0],[.56,.092,10.71],trim);
    for(let j=0;j<=6;j++){
      const z=-5.26+10.52*j/6;
      batch.box([side*2.42,.486,z],[.40,.21,.064],trim);
      batch.box([side*2.27,.529,z],[.10,.28,.075],'#967751');
    }
    batch.box([side*2.28,.650,0],[.10,.061,10.74],trim);
    batch.box([0,.431,side*6.015],[1.27,.25,.12],dark);
    batch.box([0,.431,side*6.077],[1.17,.18,.018],'#74674b');
  }
  parent.add(batch.finish(true));
}

function elephantBronzePlaque(parent){
  const material=habitatMaterial('elephantBronzePlaque',()=>{
    const canvas=document.createElement('canvas');canvas.width=1024;canvas.height=220;
    const ctx=canvas.getContext('2d'),metal=ctx.createLinearGradient(0,0,0,220);
    metal.addColorStop(0,'#4b4235');metal.addColorStop(.46,'#342e24');metal.addColorStop(1,'#302820');
    ctx.fillStyle=metal;ctx.fillRect(0,0,1024,220);ctx.strokeStyle='#9b8862';ctx.lineWidth=3.4;ctx.strokeRect(8,8,1008,204);
    ctx.strokeStyle='#594a35';ctx.lineWidth=2;ctx.strokeRect(16,15,992,190);
    ctx.textAlign='center';ctx.textBaseline='middle';ctx.shadowColor='#211b15';ctx.shadowOffsetY=2;
    ctx.fillStyle='#c9b88f';ctx.font='35px Georgia';ctx.fillText('E A S T   A F R I C A N   E L E P H A N T',512,58);
    ctx.font='italic 25px Georgia';ctx.fillText('Loxodonta africana',512,103);
    ctx.fillStyle='#af9d78';ctx.font='22px Georgia';ctx.fillText('The Alarm',512,148);
    ctx.font='15px Georgia';ctx.fillText('A K E L E Y   H A L L   O F   A F R I C A N   M A M M A L S',512,182);
    for(const x of [25,999])for(const y of [24,196]){ctx.fillStyle='#89795a';ctx.beginPath();ctx.arc(x,y,4.1,0,Math.PI*2);ctx.fill();}
    const texture=new THREE.CanvasTexture(canvas);texture.colorSpace=THREE.SRGBColorSpace;texture.anisotropy=4;
    return new THREE.MeshStandardMaterial({map:texture,roughness:.45,metalness:.27});
  });
  for(const side of [-1,1]){
    const plaque=new THREE.Mesh(new THREE.PlaneGeometry(1.19,.23),material);
    plaque.position.set(0,.431,side*6.092);plaque.rotation.y=side<0?Math.PI:0;parent.add(plaque);
  }
}

function addHabitatTrim(parent,options,place,dimensions,front,lo,hi){
  const trim=new GalleryMesh(),{key,width,caseWidth,name}=options,outer=caseWidth,inner=width;
  const box=(u,y,d,w,h,t,color)=>trim.box(place(u,y,d),dimensions(w,h,t),color);
  const stone='#77796d',lip='#aaa286',black='#393a32',olive='#5c6053';
  box(0,.28,front-.06,outer,.55,.55,black);
  box(0,.126,front+.22,outer+.035,.092,.12,'#706956');
  box(0,lo-.14,front,outer,.27,.50,stone);
  box(0,lo-.035,front+.15,inner+.08,.085,.32,lip);
  box(0,hi+.24,front-.04,outer,.52,.48,stone);
  box(0,hi+.51,front+.06,outer+.02,.072,.26,olive);
  const bodyH=hi+.52;
  for(const sign of [-1,1]){
    const gap=Math.max(.13,(outer-inner)/2);
    box(sign*(outer/2-gap/2),bodyH*.51,front-.10,gap,bodyH+.06,.72,black);
    box(sign*(inner/2+.03),.5*(hi+lo),front+.05,.078,hi-lo+.11,.24,stone);
    box(sign*(inner/2+.012),.5*(hi+lo),front+.156,.018,hi-lo+.055,.018,lip);
    for(let j=1;j<=3;j++)box(sign*(inner/2+gap*j/4),bodyH*.51,front+.277,.022,bodyH-.23,.045,olive);
  }
  parent.add(trim.finish());
  // Black-green veined marble between the glass and frieze is a prominent
  // feature of Akeley Hall. Keep each front inside its own case footprint.
  const pos=[],uv=[],ind=[];
  const offset=(key.charCodeAt(0)%7)/5,keyPhase=(key.charCodeAt(key.length-1)%9)/7;
  function marble(l,r,b,t,d){
    const v=pos.length/3;
    for(const [u,y] of [[l,b],[r,b],[r,t],[l,t]]){
      pos.push(...place(u,y,d));uv.push(offset+u*.58,keyPhase+y*.58);
    }
    ind.push(v,v+1,v+2,v,v+2,v+3);
  }
  for(const sign of [-1,1]){
    const a=sign*(inner/2+.061),b=sign*(outer/2-.005);
    if(Math.abs(a-b)>.025)marble(Math.min(a,b),Math.max(a,b),.055,bodyH+.022,front+.268);
  }
  marble(-outer/2+.006,outer/2-.006,.042,lo-.245,front+.232);
  marble(-outer/2+.012,outer/2-.012,hi+.472,hi+.519,front+.209);
  const slabs=new THREE.BufferGeometry();slabs.setAttribute('position',new THREE.Float32BufferAttribute(pos,3));
  slabs.setAttribute('uv',new THREE.Float32BufferAttribute(uv,2));slabs.setIndex(ind);slabs.computeVertexNormals();
  const facing=new THREE.Mesh(slabs,habitatMaterial('akeleyMarble',()=>new THREE.MeshStandardMaterial({map:habitatTexture('akeleyMarble'),roughness:.42,metalness:.12,side:THREE.DoubleSide})));
  parent.add(facing);
  const header=new THREE.PlaneGeometry(inner-.04,.37);
  const m=habitatMaterial('frieze',()=>new THREE.MeshStandardMaterial({map:habitatTexture('frieze'),bumpMap:habitatTexture('friezeBump',false),bumpScale:.032,roughness:.73,metalness:.21,side:THREE.DoubleSide}));
  const relief=new THREE.Mesh(header,m);relief.position.fromArray(place(0,hi+.25,front+.209));
  relief.rotation.y=Math.atan2(options.alongX?0:options.direction,options.alongX?options.direction:0);
  parent.add(relief);
  // The inscriptions on the display sills supplement the freestanding placards.
  const sillMaterial=habitatMaterial('sill-'+key,()=>{
  const c=document.createElement('canvas');c.width=768;c.height=72;
  const ctx=c.getContext('2d');
  ctx.fillStyle='#a59e83';ctx.fillRect(0,0,c.width,c.height);
  ctx.textAlign='center';ctx.textBaseline='middle';ctx.font='30px Georgia';
  ctx.fillStyle='#34352e';ctx.fillText(name.toUpperCase().split('').join(' '),384,36,720);
  const tex=new THREE.CanvasTexture(c);tex.colorSpace=THREE.SRGBColorSpace;
  return new THREE.MeshStandardMaterial({map:tex,roughness:.61,side:THREE.DoubleSide});
  });
  const title=new THREE.Mesh(new THREE.PlaneGeometry(Math.min(inner*.64,3.3),.13),sillMaterial);
  title.position.fromArray(place(0,lo-.10,front+.254));title.rotation.y=relief.rotation.y;parent.add(title);
}

